    fn add(self, other: Vec3) -> Vec3 { Vec3::new(self.x + other.x, self.y + other.y, self.z + other.z) }
    fn sub(self, other: Vec3) -> Vec3 { Vec3::new(self.x - other.x, self.y - other.y, self.z - other.z) }
    fn mul(self, s: f32) -> Vec3 { Vec3::new(self.x * s, self.y * s, self.z * s) }
    fn dot(self, other: Vec3) -> f32 { self.x * other.x + self.y * other.y + self.z * other.z }
    fn cross(self, other: Vec3) -> Vec3 {
        Vec3::new(
            self.y * other.z - self.z * other.y,
            self.z * other.x - self.x * other.z,
            self.x * other.y - self.y * other.x,
        )
    }
    fn length(self) -> f32 { self.dot(self).sqrt() }
    fn normalize(self) -> Vec3 {
        let len = self.length();
        if len > 0.0 { self.mul(1.0 / len) } else { self }
    }
}

struct Material {
    kd: (u8, u8, u8),
}

struct Triangle {
    v: [Vec3; 3],
    normal: Vec3,
    material_index: usize,
}

struct Model {
    triangles: Vec<Triangle>,
    materials: Vec<Material>,
}

fn parse_obj(filename: &str) -> Model {
    let mut triangles = Vec::new();
    let mut materials = Vec::new();
    let mut material_map = HashMap::new();
    let mut active_mat_idx = 0;

    materials.push(Material { kd: (255, 255, 255) });

    let file = File::open(filename).expect("OpenFileFailed");
    let reader = BufReader::new(file);
    let mut vertices = Vec::new();

    let obj_dir = Path::new(filename).parent().unwrap_or(Path::new("."));

    for line in reader.lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() { continue; }

        match parts[0] {
            "v" => {
                vertices.push(Vec3::new(
                    parts[1].parse().unwrap(),
                    parts[2].parse().unwrap(),
                    parts[3].parse().unwrap(),
                ));
            }
            "mtllib" => {
                let mtl_path = obj_dir.join(parts[1]);
                if let Ok(mtl_file) = File::open(mtl_path) {
                    let mtl_reader = BufReader::new(mtl_file);
                    let mut current_mat_name = String::new();
                    for mtl_line in mtl_reader.lines() {
                        let mtl_line = mtl_line.unwrap();
                        let mtl_parts: Vec<&str> = mtl_line.split_whitespace().collect();
                        if mtl_parts.is_empty() { continue; }
                        if mtl_parts[0] == "newmtl" {
                            current_mat_name = mtl_parts[1].to_string();
                        } else if mtl_parts[0] == "Kd" {
                            let r = (mtl_parts[1].parse::<f32>().unwrap() * 255.0).round() as u8;
                            let g = (mtl_parts[2].parse::<f32>().unwrap() * 255.0).round() as u8;
                            let b = (mtl_parts[3].parse::<f32>().unwrap() * 255.0).round() as u8;
                            materials.push(Material { kd: (r, g, b) });
                            material_map.insert(current_mat_name.clone(), materials.len() - 1);
                        }
                    }
                }
            }
            "usemtl" => {
                active_mat_idx = *material_map.get(parts[1]).unwrap_or(&0);
            }
            "f" => {
                let mut face_v = Vec::new();
                for p in &parts[1..] {
                    let v_idx: Vec<&str> = p.split('/').collect();
                    let idx: i32 = v_idx[0].parse().unwrap();
                    let v = if idx > 0 { vertices[(idx - 1) as usize] } else { vertices[(vertices.len() as i32 + idx) as usize] };
                    face_v.push(v);
                }
                for i in 1..face_v.len() - 1 {
                    let v0 = face_v[0];
                    let v1 = face_v[i];
                    let v2 = face_v[i+1];
                    let normal = v1.sub(v0).cross(v2.sub(v0)).normalize();
                    triangles.push(Triangle { v: [v0, v1, v2], normal, material_index: active_mat_idx });
                }
            }
            _ => {}
        }
    }

