    let size = max_v.sub(min_v);
    let max_dim = size.x.max(size.y).max(size.z);
    let scale = if max_dim > 0.0 { 1.0 / max_dim } else { 1.0 };

    for t in &mut triangles {
        for v in &mut t.v {
            *v = v.sub(center).mul(scale);
        }
    }

    Model { triangles, materials }
}

fn rotate(v: Vec3, yaw: f32, pitch: f32, roll: f32) -> Vec3 {
    let (sy, cy) = yaw.sin_cos();
    let (sp, cp) = pitch.sin_cos();
    let (sr, cr) = roll.sin_cos();
    // Rotate around X (yaw)
    let y1 = v.y * cy - v.z * sy;
    let z1 = v.y * sy + v.z * cy;
    let v = Vec3::new(v.x, y1, z1);
    // Rotate around Y (pitch)
    let x2 = v.x * cp + v.z * sp;
    let z2 = -v.x * sp + v.z * cp;
    let v = Vec3::new(x2, v.y, z2);
    // Rotate around Z (roll)
    let x3 = v.x * cr - v.y * sr;
    let y3 = v.x * sr + v.y * cr;
    Vec3::new(x3, y3, v.z)
}

