                    let v0 = face_v[0];
                    let v1 = face_v[i];
                    let v2 = face_v[i+1];
                    let normal = v1.sub(v0).cross(v2.sub(v0)).normalize();
                    triangles.push(Triangle { v: [v0, v1, v2], normal, material_index: active_mat_idx });
                }
            }
            _ => {}
        }
    }

    if triangles.is_empty() { return Model { triangles, materials }; }

    let mut min_v = triangles[0].v[0];
    let mut max_v = triangles[0].v[0];
    for t in &triangles {
        for v in &t.v {
            min_v.x = min_v.x.min(v.x); min_v.y = min_v.y.min(v.y); min_v.z = min_v.z.min(v.z);
            max_v.x = max_v.x.max(v.x); max_v.y = max_v.y.max(v.y); max_v.z = max_v.z.max(v.z);
        }
    }
    let center = min_v.add(max_v).mul(0.5);
    let size = max_v.sub(min_v);
    let max_dim = size.x.max(size.y).max(size.z);
    let scale = if max_dim > 0.0 { 1.0 / max_dim } else { 1.0 };

    for t in &mut triangles {
        for v in &mut t.v {
            *v = v.sub(center).mul(scale);
        }
    }

    Model { triangles, materials }
}

fn rotate(v: Vec3, yaw: f32, pitch: f32, roll: f32) -> Vec3 {
    let (sy, cy) = yaw.sin_cos();
    let (sp, cp) = pitch.sin_cos();
    let (sr, cr) = roll.sin_cos();
    // Rotate around X (yaw)
    let y1 = v.y * cy - v.z * sy;
    let z1 = v.y * sy + v.z * cy;
    let v = Vec3::new(v.x, y1, z1);
    // Rotate around Y (pitch)
    let x2 = v.x * cp + v.z * sp;
    let z2 = -v.x * sp + v.z * cp;
    let v = Vec3::new(x2, v.y, z2);
    // Rotate around Z (roll)
    let x3 = v.x * cr - v.y * sr;
    let y3 = v.x * sr + v.y * cr;
    Vec3::new(x3, y3, v.z)
}

fn render(model: &Model, width: usize, height: usize, yaw: f32, pitch: f32, roll: f32, webify: bool) -> String {
    let mut z_buffer = vec![f32::NEG_INFINITY; width * height];
    let mut color_buffer = vec![(0, 0, 0); width * height];
    let mut char_buffer = vec![' '; width * height];
    let ramp = " .:-=+*#%@".as_bytes();

    for t in &model.triangles {
        let mut v = [
            rotate(t.v[0], yaw, pitch, roll),
            rotate(t.v[1], yaw, pitch, roll),
            rotate(t.v[2], yaw, pitch, roll),
        ];
        let normal = rotate(t.normal, yaw, pitch, roll);
        let intensity = normal.dot(Vec3::new(0.0, 0.0, 1.0)).max(0.0);
        if intensity <= 0.0 && normal.dot(Vec3::new(0.0, 0.0, 1.0)) < 0.0 { continue; } // Cull backfaces

        let char_idx = (intensity * 10.0).floor() as usize;
        let c = ramp[char_idx.min(9)] as char;
        if c == ' ' && !webify { continue; }

        // Scale to fit screen (preserving aspect ratio)
        // Characters are 1x2, so we scale Y by 0.5 effectively.
        // Actually, we scale the model to fit in a -0.9..0.9 range.
        let scale_factor = 0.9 * (width as f32).min(height as f32 * 2.0);
        for vi in &mut v {
            vi.x = vi.x * scale_factor + (width as f32 / 2.0);
            vi.y = -vi.y * (scale_factor / 2.0) + (height as f32 / 2.0);
        }

        let (mut min_x, mut max_x) = (v[0].x.min(v[1].x).min(v[2].x) as i32, v[0].x.max(v[1].x).max(v[2].x) as i32);
        let (mut min_y, mut max_y) = (v[0].y.min(v[1].y).min(v[2].y) as i32, v[0].y.max(v[1].y).max(v[2].y) as i32);
        min_x = min_x.max(0); max_x = max_x.min(width as i32 - 1);
        min_y = min_y.max(0); max_y = max_y.min(height as i32 - 1);

        for y in min_y..=max_y {
            for x in min_x..=max_x {
                let p = Vec3::new(x as f32 + 0.5, y as f32 + 0.5, 0.0);
                let area = (v[1].x - v[0].x) * (v[2].y - v[0].y) - (v[1].y - v[0].y) * (v[2].x - v[0].x);
                let w0 = ((v[1].x - p.x) * (v[2].y - p.y) - (v[1].y - p.y) * (v[2].x - p.x)) / area;
                let w1 = ((v[2].x - p.x) * (v[0].y - p.y) - (v[2].y - p.y) * (v[0].x - p.x)) / area;
                let w2 = 1.0 - w0 - w1;

                if w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 {
                    let z = w0 * v[0].z + w1 * v[1].z + w2 * v[2].z;
                    if z > z_buffer[(y as usize * width + x as usize)] {
                        z_buffer[(y as usize * width + x as usize)] = z;
                        color_buffer[(y as usize * width + x as usize)] = model.materials[t.material_index].kd;
                        char_buffer[(y as usize * width + x as usize)] = c;
                    }
                }
            }
        }
    }

    let mut out = String::new();
    if webify {
        for y in 0..height {
            for x in 0..width {
                let (r, g, b) = color_buffer[y * width + x];
                let c = char_buffer[y * width + x];
                out.push_str(&format!("<span style=\"color:rgb({},{},{})\">{}</span>", r, g, b, c));
            }
            out.push('\n');
        }
    } else {
        for y in 0..height {
            for x in 0..width {
                let (r, g, b) = color_buffer[y * width + x];
                let c = char_buffer[y * width + x];
                if c == ' ' {
                    out.push_str("\x1b[48;2;25;25;25m\x1b[38;2;0;0;0m \x1b[49m\x1b[39m");
                } else {
                    out.push_str(&format!("\x1b[48;2;25;25;25m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m", r, g, b, c));
                }
            }
            out.push('\n');
        }
    }
    out
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }

    let mut filenames = Vec::new();
    let mut i = 1;
    while i < args.len() && !args[i].starts_with('-') && args[i] != "image" && args[i] != "help" {
        filenames.push(args[i].clone());
        i += 1;
    }

    let mut model = Model { triangles: Vec::new(), materials: Vec::new() };
    for f in filenames {
        let m = parse_obj(&f);
        model.triangles.extend(m.triangles);
        if model.materials.is_empty() { model.materials = m.materials; }
        else { model.materials.extend(m.materials); }
    }

    let mut yaw = 0.0; let mut pitch = 0.0; let mut roll = 0.0;
    let mut width = 80; let mut height = 24;
    let mut webify_frames = 0;

    let mut j = i;
    while j < args.len() {
        match args[j].as_str() {
            "-x" | "--yaw" => { yaw = args[j+1].parse().unwrap(); j += 2; }
            "-y" | "--pitch" => { pitch = args[j+1].parse().unwrap(); j += 2; }
            "-z" | "--roll" => { roll = args[j+1].parse().unwrap(); j += 2; }
            "-w" => { width = args[j+1].parse().unwrap(); j += 2; }
            "-h" => { height = args[j+1].parse().unwrap(); j += 2; }
            "-j" | "--webify" => { webify_frames = args[j+1].parse().unwrap(); j += 2; }
            "image" => { j += 1; }
            _ => { j += 1; }
        }
    }

    if webify_frames > 0 {
        println!("let frames = [");
        for f in 0..webify_frames {
            let frame_yaw = yaw + (f as f32 * 2.0 * std::f32::consts::PI / webify_frames as f32);
            let rendered = render(&model, width, height, frame_yaw, pitch, roll, true);
            print!("`\n{}`", rendered);
            if f < webify_frames - 1 { println!(","); }
        }
        println!("\n];");
    } else if args.contains(&"image".to_string()) {
        let rendered = render(&model, width, height, yaw, pitch, roll, false);
        // Remove trailing newlines to match the original behavior of "image" command
        print!("{}", rendered.trim_end_matches('\n'));
    } else {
        // Interactive mode (simplified)
        print!("\x1b[?25l"); // Hide cursor
        loop {
            let rendered = render(&model, width, height, yaw, pitch, roll, false);
            print!("\x1b[1;1H{}", rendered);
            io::stdout().flush().unwrap();
            // In a real implementation, we would read keys here.
            // Since we can't easily do that without dependencies, we just exit for now or loop.
            break; 
        }
        print!("\x1b[?25h"); // Show cursor
    }
}
