}

impl Vec3 {
    fn new(x: f32, y: f32, z: f32) -> Self { Vec3 { x, y, z } }
    fn add(self, other: Vec3) -> Vec3 { Vec3::new(self.x + other.x, self.y + other.y, self.z + other.z) }
    fn sub(self, other: Vec3) -> Vec3 { Vec3::new(self.x - other.x, self.y - other.y, self.z - other.z) }
    fn mul(self, s: f32) -> Vec3 { Vec3::new(self.x * s, self.y * s, self.z * s) }
    fn dot(self, other: Vec3) -> f32 { self.x * other.x + self.y * other.y + self.z * other.z }
    fn cross(self, other: Vec3) -> Vec3 {
        Vec3::new(
            self.y * other.z - self.z * other.y,
            self.z * other.x - self.x * other.z,
            self.x * other.y - self.y * other.x,
        )
    }
    fn length(self) -> f32 { self.dot(self).sqrt() }
    fn normalize(self) -> Vec3 {
        let len = self.length();
        if len > 1e-6 { self.mul(1.0 / len) } else { Vec3::new(0.0, 0.0, 0.0) }
    }
}

struct Material {
    kd: (u8, u8, u8),
}

struct Triangle {
    v: [Vec3; 3],
    normal: Vec3,
    material_index: usize,
}

struct Model {
    triangles: Vec<Triangle>,
    materials: Vec<Material>,
}

fn parse_obj(filename: &str) -> Model {
    let mut triangles = Vec::new();
    let mut materials = Vec::new();
    let mut material_map = HashMap::new();
    let mut active_mat_idx = 0;
    materials.push(Material { kd: (255, 255, 255) });
    let file = File::open(filename).expect("OpenFileFailed");
    let reader = BufReader::new(file);
    let mut vertices = Vec::new();
    let obj_dir = Path::new(filename).parent().unwrap_or(Path::new("."));
    for line in reader.lines() {
        let line = if let Ok(l) = line { l } else { continue; };
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() { continue; }
        match parts[0] {
            "v" => { vertices.push(Vec3::new(parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap())); }
            "mtllib" => {
                let mtl_path = obj_dir.join(parts[1]);
                if let Ok(mtl_file) = File::open(mtl_path) {
                    let mtl_reader = BufReader::new(mtl_file);
                    let mut current_mat_name = String::new();
                    for mtl_line in mtl_reader.lines() {
                        let mtl_line = if let Ok(l) = mtl_line { l } else { continue; };
                        let mtl_parts: Vec<&str> = mtl_line.split_whitespace().collect();
                        if mtl_parts.is_empty() { continue; }
                        if mtl_parts[0] == "newmtl" { current_mat_name = mtl_parts[1].to_string(); }
                        else if mtl_parts[0] == "Kd" {
                            let r = (mtl_parts[1].parse::<f32>().unwrap() * 255.0).round() as u8;
                            let g = (mtl_parts[2].parse::<f32>().unwrap() * 255.0).round() as u8;
                            let b = (mtl_parts[3].parse::<f32>().unwrap() * 255.0).round() as u8;
                            materials.push(Material { kd: (r, g, b) });
                            material_map.insert(current_mat_name.clone(), materials.len() - 1);
                        }
                    }
                }
            }
            "usemtl" => { active_mat_idx = *material_map.get(parts[1]).unwrap_or(&0); }
            "f" => {
                let mut face_v = Vec::new();
                for p in &parts[1..] {
                    let v_idx: Vec<&str> = p.split('/').collect();
                    let idx: i32 = v_idx[0].parse().unwrap();
                    let v = if idx > 0 { vertices[(idx - 1) as usize] } else { vertices[(vertices.len() as i32 + idx) as usize] };
                    face_v.push(v);
                }
                for i in 1..face_v.len() - 1 {
                    let v0 = face_v[0]; let v1 = face_v[i]; let v2 = face_v[i+1];
                    let normal = v1.sub(v0).cross(v2.sub(v0)).normalize();
                    triangles.push(Triangle { v: [v0, v1, v2], normal, material_index: active_mat_idx });
                }
            }
            _ => {}
        }
    }
    if triangles.is_empty() { return Model { triangles, materials }; }
    let mut min_v = Vec3::new(f32::INFINITY, f32::INFINITY, f32::INFINITY);
    let mut max_v = Vec3::new(f32::NEG_INFINITY, f32::NEG_INFINITY, f32::NEG_INFINITY);
    for t in &triangles {
        for v in &t.v {
            min_v.x = min_v.x.min(v.x); min_v.y = min_v.y.min(v.y); min_v.z = min_v.z.min(v.z);
            max_v.x = max_v.x.max(v.x); max_v.y = max_v.y.max(v.y); max_v.z = max_v.z.max(v.z);
        }
    }
    let center = min_v.add(max_v).mul(0.5);
    let size = max_v.sub(min_v);
    let max_dim = size.x.max(size.y).max(size.z);
    let scale = if max_dim > 0.0 { 1.0 / max_dim } else { 1.0 };
    for t in &mut triangles {
        for v in &mut t.v { *v = v.sub(center).mul(scale); }
        t.normal = t.v[1].sub(t.v[0]).cross(t.v[2].sub(t.v[0])).normalize();
    }
    Model { triangles, materials }
}

fn rotate(v: Vec3, yaw: f32, pitch: f32, roll: f32) -> Vec3 {
    let (sy, cy) = yaw.sin_cos();
    let (sp, cp) = pitch.sin_cos();
    let (sr, cr) = roll.sin_cos();
    let y1 = v.y * cy - v.z * sy; let z1 = v.y * sy + v.z * cy; let v = Vec3::new(v.x, y1, z1);
    let x2 = v.x * cp + v.z * sp; let z2 = -v.x * sp + v.z * cp; let v = Vec3::new(x2, v.y, z2);
    let x3 = v.x * cr - v.y * sr; let y3 = v.x * sr + v.y * cr; Vec3::new(x3, y3, v.z)
}

fn render(model: &Model, width: usize, height: usize, yaw: f32, pitch: f32, roll: f32, webify: bool) -> String {
    let mut z_buffer = vec![f32::NEG_INFINITY; width * height];
    let mut color_buffer = vec![(0, 0, 0); width * height];
    let mut char_buffer = vec![' '; width * height];
    let ramp = " .:-=+*#%@".as_bytes();
    for t in &model.triangles {
        let v_rot = [rotate(t.v[0], yaw, pitch, roll), rotate(t.v[1], yaw, pitch, roll), rotate(t.v[2], yaw, pitch, roll)];
        let normal_rot = rotate(t.normal, yaw, pitch, roll);
        let dot = normal_rot.dot(Vec3::new(0.0, 0.0, 1.0));
        if dot < 0.0 { continue; }
        let intensity = dot.min(1.0);
        let char_idx = (1.0 + (intensity * 8.99)).floor() as usize;
        let c = ramp[char_idx.min(9)] as char;
        let mut v_screen = v_rot;
        let scale_factor = 0.9 * (width as f32).min(height as f32 * 2.0);
        for vi in &mut v_screen {
            vi.x = vi.x * scale_factor + (width as f32 / 2.0);
            vi.y = -vi.y * (scale_factor / 2.0) + (height as f32 / 2.0);
        }
        let (min_x, max_x) = (v_screen[0].x.min(v_screen[1].x).min(v_screen[2].x).floor() as i32, v_screen[0].x.max(v_screen[1].x).max(v_screen[2].x).ceil() as i32);
        let (min_y, max_y) = (v_screen[0].y.min(v_screen[1].y).min(v_screen[2].y).floor() as i32, v_screen[0].y.max(v_screen[1].y).max(v_screen[2].y).ceil() as i32);
        for py in min_y.max(0)..=max_y.min(height as i32 - 1) {
            for px in min_x.max(0)..=max_x.min(width as i32 - 1) {
                let p = Vec3::new(px as f32 + 0.5, py as f32 + 0.5, 0.0);
                let v0 = v_screen[0]; let v1 = v_screen[1]; let v2 = v_screen[2];
                let area = (v1.x - v0.x) * (v2.y - v0.y) - (v1.y - v0.y) * (v2.x - v0.x);
                let w0 = ((v1.x - p.x) * (v2.y - p.y) - (v1.y - p.y) * (v2.x - p.x)) / area;
                let w1 = ((v2.x - p.x) * (v0.y - p.y) - (v2.y - p.y) * (v0.x - p.x)) / area;
                let w2 = 1.0 - w0 - w1;
                if w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 {
                    let z = w0 * v_rot[0].z + w1 * v_rot[1].z + w2 * v_rot[2].z;
                    if z > z_buffer[py as usize * width + px as usize] {
                        z_buffer[py as usize * width + px as usize] = z;
                        color_buffer[py as usize * width + px as usize] = model.materials[t.material_index].kd;
                        char_buffer[py as usize * width + px as usize] = c;
                    }
                }
            }
        }
    }
    let mut out = String::new();
    for y in 0..height {
        for x in 0..width {
            let (r, g, b) = color_buffer[y * width + x];
            let c = char_buffer[y * width + x];
            if webify { out.push_str(&format!("<span style=\"color:rgb({},{},{})\">{}</span>", r, g, b, c)); }
            else {
                if c == ' ' { out.push_str("\x1b[48;2;25;25;25m\x1b[38;2;0;0;0m \x1b[49m\x1b[39m"); }
                else { out.push_str(&format!("\x1b[48;2;25;25;25m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m", r, g, b, c)); }
            }
        }
        if y < height - 1 || webify { out.push('\n'); }
    }
    out
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut filenames = Vec::new();
    let mut yaw = 0.0; let mut pitch = 0.0; let mut roll = 0.0;
    let mut width = 80; let mut height = 24; let mut webify_frames = 0;
    let mut is_image = false;
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-x" | "--yaw" => { yaw = args[i+1].parse().unwrap(); i += 2; }
            "-y" | "--pitch" => { pitch = args[i+1].parse().unwrap(); i += 2; }
            "-z" | "--roll" => { roll = args[i+1].parse().unwrap(); i += 2; }
            "-w" => { width = args[i+1].parse().unwrap(); i += 2; }
            "-h" => { if i+1 < args.len() && args[i+1].parse::<usize>().is_ok() { height = args[i+1].parse().unwrap(); i += 2; } else { i += 1; } }
            "-j" | "--webify" => { webify_frames = args[i+1].parse().unwrap(); i += 2; }
            "image" => { is_image = true; i += 1; }
            _ => { if !args[i].starts_with('-') { filenames.push(args[i].clone()); } i += 1; }
        }
    }
    let mut scene_model = Model { triangles: Vec::new(), materials: Vec::new() };
    for f in filenames {
        let mut m = parse_obj(&f);
        let mat_offset = scene_model.materials.len();
        for t in &mut m.triangles { t.material_index += mat_offset; }
        scene_model.triangles.extend(m.triangles);
        scene_model.materials.extend(m.materials);
    }
    if webify_frames > 0 {
        println!("let frames = [");
        for f in 0..webify_frames {
            let f_yaw = yaw + (f as f32 * 2.0 * std::f32::consts::PI / webify_frames as f32);
            let rendered = render(&scene_model, width, height, f_yaw, pitch, roll, true);
            print!("`\n{}`", rendered);
            if f < webify_frames - 1 { println!(","); }
        }
        println!("\n];");
    } else if is_image {
        print!("{}", render(&scene_model, width, height, yaw, pitch, roll, false));
    } else {
        print!("\x1b[?25l");
        let rendered = render(&scene_model, width, height, yaw, pitch, roll, false);
        print!("\x1b[1;1H{}", rendered);
        io::stdout().flush().unwrap();
        print!("\x1b[?25h");
    }
}
